message.content:
{
  "issues": [
    "完整档字段格式不符：fears 应为数组，草稿中为字符串。",
    "背景中提及“丈夫早故”，属于给定身份外的亲属与婚姻信息，违反硬性要求。",
    "背景中“换些米粮”涉及财物交换，违反不写钱物的要求。",
    "关系备注中“长子”与给定关系“子女”不一致，且“长子”暗示其他子女排序，超出给定信息。"
  ],
  "profile": {
    "personality": {
      "traits": [
        "沉静寡言",
        "细致耐心",
        "知足安分"
      ],
      "values": [
        "把字写好，把事做对",
        "一家人平安相守"
      ],
      "flaws": "不善与人争执，遇事常自己忍下"
    },
    "voice": {
      "register": "平实浅白，带几分书卷气",
      "accent": "东学一带的软缓口音，尾音轻",
      "habits": [
        "说话前先停一停",
        "抄写时习惯低声念出字句"
      ],
      "samples": [
        "这页墨色还匀，晾一晾再收罢。",
        "荣儿，灯祠的灯芯该剪了，莫要贪玩。",
        "字是死的，人是活的，慢慢来就顺了。"
      ]
    },
    "background": "廖生自小在东学长大，识得几个字，便替学馆抄录讲义、描摹字样板，一抄就是许多年。她独自拉扯廖荣和廖贞，白日伏案，傍晚去灯祠添油剪芯。日子清苦却安稳，她只盼两个孩子识得字、走得正。",
    "currentConcern": "荣儿近来贪玩，字越写越潦草，贞儿又总咳嗽，她心里放不下。",
    "goals": [
      "把学馆这季的讲义抄完，不出错字。",
      "教廖荣把字写端正，教廖贞认得几个常用字。"
    ],
    "fears": [
      "怕自己眼力不济，抄错了字，误了学馆里的孩子。"
    ],
    "knowledge": {
      "unknown": [
        "东学之外各坊的街巷与人事",
        "灯祠所供灯盏的来历与旧闻"
      ]
    },
    "relationships": [
      {
        "with": "npc_pop_bs_014_2",
        "relation": "子女",
        "note": "性子跳脱，写字总想快，她每日收工后必查他的功课。"
      },
      {
        "with": "npc_pop_bs_014_3",
        "relation": "子女",
        "note": "体弱怕冷，她抄书时常让她坐在脚边暖着。"
      }
    ],
    "visibleFeature": "指节上有多年握笔磨出的薄茧，衣襟常沾着洗不净的墨点。"
  }
}
